#!/usr/bin/env python3
"""Token Monitoring Tool for Long-Running Coding Sessions"""

import json
from pathlib import Path

# Paths
INPUT_DIR = Path('input')
OUTPUT_DIR = Path('output')
SESSION_FILE = INPUT_DIR / 'session.json'
ALERT_CONFIG_FILE = OUTPUT_DIR / 'alert_config.json'
STATUS_FILE = OUTPUT_DIR / 'status_report.txt'

def load_session_data():
    """Load session data from JSON file."""
    with open(SESSION_FILE, 'r', encoding='utf-8') as f:
        return json.load(f)

def calculate_usage(used, limit):
    """Calculate usage percentage."""
    return (used / limit) * 100

def create_progress_bar(percentage, width=30):
    """Create a material design progress bar with box-style (▰/▱)."""
    filled = int(width * percentage / 100)
    empty = width - filled
    return '▰' * filled + '▱' * empty

def get_status_level(percentage):
    """Determine status level based on percentage."""
    if percentage >= 95:
        return ('🚨', 'Emergency', 'Red Zone')
    elif percentage >= 90:
        return ('🔴', 'Critical Warning', 'Red Zone')
    elif percentage >= 75:
        return ('🔶', 'High Warning', 'Rot-Orange Zone')
    elif percentage >= 50:
        return ('🟠', 'Medium Warning', 'Orange Zone')
    elif percentage >= 25:
        return ('🟡', 'Low Warning', 'Yellow Zone')
    else:
        return ('✅', 'OK', 'Green Zone')

def get_recommendations(status_level):
    """Get recommendations based on status level."""
    recommendations = {
        'Emergency': ['⚠️  CRITICAL: Tokens nearly exhausted!', '🔄 Start new session immediately', '💾 Save all work now'],
        'Critical Warning': ['🔄 Prepare new session', '💾 Save important work', '📝 Token-sparend arbeiten'],
        'High Warning': ['✅ Wichtige Entscheidungen jetzt treffen', '✅ Neue Session vorbereiten', '✅ Token-sparend arbeiten'],
        'Medium Warning': ['📊 Monitor usage closely', '💡 Consider session planning'],
        'Low Warning': ['👍 Keep monitoring', '💡 Plan ahead for heavy tasks'],
        'OK': ['✅ Good token availability', '👍 Continue working normally']
    }
    return recommendations.get(status_level, ['👍 Continue working'])

def estimate_remaining_sessions(remaining, avg_session=50000):
    """Estimate remaining sessions."""
    if remaining <= 0:
        return 0
    return max(1, int(remaining / avg_session))

def generate_status_report(session_data):
    """Generate a terminal status report."""
    limit = session_data['limit']
    used = session_data['used']
    remaining = limit - used
    percentage = calculate_usage(used, limit)

    icon, status, zone = get_status_level(percentage)
    progress_bar = create_progress_bar(percentage)
    sessions_left = estimate_remaining_sessions(remaining)
    recommendations = get_recommendations(status)

    report = f"""{icon} Token Alert: Achtung!

{icon} {progress_bar} {percentage:.1f}%
{used:,} / {limit:,} Tokens verwendet

⚠️ Status: {status} ({zone})
💡 Verbleibend: ~{remaining:,} Tokens
⏰ Geschätzte Sessions: {sessions_left} Session{'s' if sessions_left != 1 else ''}

🔧 Empfehlung:
   {chr(10)}   '.join(recommendations)}

---
Session ID: {session_data['session_id']}
Note: {session_data['note']}
"""
    return report

def generate_alert_config(session_data):
    """Generate alert configuration file."""
    thresholds = session_data.get('thresholds', [75, 90, 95])

    config = {
        'session_id': session_data['session_id'],
        'note': session_data['note'],
        'limit': session_data['limit'],
        'thresholds': [
            {
                'percentage': t,
                'token_value': int(session_data['limit'] * t / 100),
                'alert_level': get_alert_level(t)
            }
            for t in thresholds
        ],
        'current_usage': {
            'used': session_data['used'],
            'percentage': calculate_usage(session_data['used'], session_data['limit'])
        }
    }
    return config

def get_alert_level(percentage):
    """Get alert level for a threshold."""
    if percentage >= 95:
        return 'EMERGENCY'
    elif percentage >= 90:
        return 'CRITICAL'
    elif percentage >= 75:
        return 'HIGH'
    else:
        return 'WARNING'

def main():
    """Main function."""
    # Ensure output directory exists
    OUTPUT_DIR.mkdir(exist_ok=True)

    # Load session data
    session_data = load_session_data()

    # Generate and save status report
    report = generate_status_report(session_data)
    STATUS_FILE.write_text(report, encoding='utf-8')
    print(report)

    # Generate and save alert configuration
    alert_config = generate_alert_config(session_data)
    with open(ALERT_CONFIG_FILE, 'w', encoding='utf-8') as f:
        json.dump(alert_config, f, indent=2)

    print(f"\n📁 Alert configuration saved to: {ALERT_CONFIG_FILE}")
    print(f"📁 Status report saved to: {STATUS_FILE}")

if __name__ == '__main__':
    main()
